import{_ as a,o as s,c as i,a6 as n}from"./chunks/framework.DL_pga9_.js";const g=JSON.parse('{"title":"ORGASM Backend","description":"","frontmatter":{},"headers":[],"relativePath":"guide/orgasm-backend.md","filePath":"guide/orgasm-backend.md","lastUpdated":1781686130000}'),t={name:"guide/orgasm-backend.md"};function l(o,e,r,d,h,c){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="orgasm-backend" tabindex="-1">ORGASM Backend <a class="header-anchor" href="#orgasm-backend" aria-label="Permalink to “ORGASM Backend”">​</a></h1><p>ORGASM is NG&#39;s bytecode compilation and virtual machine backend. It compiles type-checked AST into compact bytecode modules (<code>.ngo</code> files), which are then executed by a stack-based VM.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>The NG execution pipeline:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Source (.ng)</span></span>
<span class="line"><span>    → Lexer → Parser → AST</span></span>
<span class="line"><span>    → Type Checker</span></span>
<span class="line"><span>    → ORGASM Compiler → Bytecode (.ngo)</span></span>
<span class="line"><span>    → ORGASM VM → Result</span></span></code></pre></div><h2 id="compilation-pipeline" tabindex="-1">Compilation Pipeline <a class="header-anchor" href="#compilation-pipeline" aria-label="Permalink to “Compilation Pipeline”">​</a></h2><h3 id="default-behavior" tabindex="-1">Default Behavior <a class="header-anchor" href="#default-behavior" aria-label="Permalink to “Default Behavior”">​</a></h3><p>The <code>ngi</code> interpreter uses ORGASM by default:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/ngi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example/01.id.ng</span></span></code></pre></div><p>This triggers: parse → type-check → compile → run.</p><h3 id="emitting-bytecode" tabindex="-1">Emitting Bytecode <a class="header-anchor" href="#emitting-bytecode" aria-label="Permalink to “Emitting Bytecode”">​</a></h3><p>Compile to <code>.ngo</code> without running:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/ngi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-ngo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> output.ngo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example/01.id.ng</span></span></code></pre></div><h3 id="running-pre-compiled-bytecode" tabindex="-1">Running Pre-compiled Bytecode <a class="header-anchor" href="#running-pre-compiled-bytecode" aria-label="Permalink to “Running Pre-compiled Bytecode”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/ngi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --run-bytecode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> output.ngo</span></span></code></pre></div><h3 id="using-the-ast-interpreter-stupid" tabindex="-1">Using the AST Interpreter (STUPID) <a class="header-anchor" href="#using-the-ast-interpreter-stupid" aria-label="Permalink to “Using the AST Interpreter (STUPID)”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/ngi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stupid</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example/01.id.ng</span></span></code></pre></div><h2 id="bytecode-modules-ngo" tabindex="-1">Bytecode Modules (<code>.ngo</code>) <a class="header-anchor" href="#bytecode-modules-ngo" aria-label="Permalink to “Bytecode Modules (.ngo)”">​</a></h2><p>A <code>.ngo</code> file contains a complete compiled module with:</p><ul><li><strong>Constants pool</strong> — string and numeric literals</li><li><strong>Function definitions</strong> — bytecode instructions per function</li><li><strong>Type descriptors</strong> — type information for runtime dispatch</li><li><strong>Import/Export table</strong> — module dependencies and visible symbols</li><li><strong>Source hash</strong> — for staleness detection</li></ul><h3 id="module-loading" tabindex="-1">Module Loading <a class="header-anchor" href="#module-loading" aria-label="Permalink to “Module Loading”">​</a></h3><p>When importing modules, the loader:</p><ol><li>Looks for <code>module.ngo</code> alongside <code>module.ng</code></li><li>If found, checks the source hash matches the current source</li><li>If hash matches, loads the bytecode directly (fast)</li><li>If hash is stale or no artifact, compiles from source</li></ol><h3 id="module-merging" tabindex="-1">Module Merging <a class="header-anchor" href="#module-merging" aria-label="Permalink to “Module Merging”">​</a></h3><p>When multiple modules are linked, ORGASM can <strong>merge</strong> bytecode modules:</p><ul><li>Remaps type operands across module boundaries</li><li>Rebuilds function indices</li><li>Prefixes exports to avoid name conflicts</li></ul><h2 id="bytecode-instruction-set" tabindex="-1">Bytecode Instruction Set <a class="header-anchor" href="#bytecode-instruction-set" aria-label="Permalink to “Bytecode Instruction Set”">​</a></h2><p>Key opcodes include:</p><table tabindex="0"><thead><tr><th>Category</th><th>Opcodes</th></tr></thead><tbody><tr><td><strong>Constants</strong></td><td><code>PUSH_I32</code>, <code>PUSH_F64</code>, <code>PUSH_BOOL</code>, <code>PUSH_STR</code>, <code>PUSH_UNIT</code></td></tr><tr><td><strong>Variables</strong></td><td><code>LOAD</code>, <code>STORE</code>, <code>LOAD_LOCAL</code>, <code>STORE_LOCAL</code>, <code>LOAD_GLOBAL</code></td></tr><tr><td><strong>Operations</strong></td><td><code>ADD</code>, <code>SUB</code>, <code>MUL</code>, <code>DIV</code>, <code>MOD</code>, <code>NEG</code>, <code>EQ</code>, <code>NE</code>, <code>LT</code>, <code>GT</code>, <code>LE</code>, <code>GE</code></td></tr><tr><td><strong>Control</strong></td><td><code>JUMP</code>, <code>JUMP_IF_FALSE</code>, <code>CALL</code>, <code>CALL_NATIVE</code>, <code>RETURN</code></td></tr><tr><td><strong>Memory</strong></td><td><code>NEW</code>, <code>FIELD_LOAD</code>, <code>FIELD_STORE</code>, <code>DEREF_LOAD</code>, <code>DEREF_STORE</code>, <code>MOVE</code></td></tr><tr><td><strong>Arrays</strong></td><td><code>ARRAY_NEW</code>, <code>ARRAY_GET</code>, <code>ARRAY_SET</code>, <code>ARRAY_LEN</code>, <code>ARRAY_APPEND</code></td></tr><tr><td><strong>Tagged Unions</strong></td><td><code>MAKE_VARIANT</code>, <code>VARIANT_TAG</code>, <code>SWITCH</code></td></tr><tr><td><strong>Traits</strong></td><td><code>TRAIT_IMPL_CALL</code>, <code>TRAIT_OBJ_CALL</code>, <code>TRAIT_CAST</code></td></tr><tr><td><strong>Modules</strong></td><td><code>CALL_IMPORT</code>, <code>LOAD_IMPORT</code></td></tr></tbody></table><h2 id="native-function-bridge" tabindex="-1">Native Function Bridge <a class="header-anchor" href="#native-function-bridge" aria-label="Permalink to “Native Function Bridge”">​</a></h2><p>Native (C++) functions can be registered with the VM:</p><div class="language-cpp"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;orgasm/vm.hpp&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">NG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orgasm</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::VM vm{modulePaths};</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Register a simple native function</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">vm.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">register_native</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my_function&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [](</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> y</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) -&gt; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;result: &quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">to_string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> y);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">vm.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(bytecode);</span></span></code></pre></div><h3 id="how-native-bridging-works" tabindex="-1">How Native Bridging Works <a class="header-anchor" href="#how-native-bridging-works" aria-label="Permalink to “How Native Bridging Works”">​</a></h3><ol><li>NG source declares <code>fun my_function(x: i32, y: f64) -&gt; string = native;</code></li><li>The compiler emits <code>CALL_NATIVE</code> with the function name</li><li>The VM looks up the registered native by name</li><li>The native bridge automatically converts between NG <code>StorageCell</code> values and C++ types</li><li>Return values are marshaled back into the VM stack</li></ol><h3 id="standard-library-natives" tabindex="-1">Standard Library Natives <a class="header-anchor" href="#standard-library-natives" aria-label="Permalink to “Standard Library Natives”">​</a></h3><p>The prelude registers native functions:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Prelude natives include:</span></span>
<span class="line"><span>fun print&lt;T...&gt;(args: T...) -&gt; unit = native;</span></span>
<span class="line"><span>fun assert&lt;T...&gt;(condition: T...) -&gt; unit = native;</span></span>
<span class="line"><span>fun not(value: bool) -&gt; bool = native;</span></span>
<span class="line"><span>fun len&lt;T&gt;(xs: T) -&gt; i32 = native;</span></span></code></pre></div><h3 id="custom-native-libraries" tabindex="-1">Custom Native Libraries <a class="header-anchor" href="#custom-native-libraries" aria-label="Permalink to “Custom Native Libraries”">​</a></h3><p>You can create and register your own native libraries:</p><div class="language-cpp"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;orgasm/native_bridge.hpp&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Register a group of related natives</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">NG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">library</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">my_library</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">register_vm_natives</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(vm);</span></span></code></pre></div><h2 id="vm-architecture" tabindex="-1">VM Architecture <a class="header-anchor" href="#vm-architecture" aria-label="Permalink to “VM Architecture”">​</a></h2><h3 id="stack-based-execution" tabindex="-1">Stack-Based Execution <a class="header-anchor" href="#stack-based-execution" aria-label="Permalink to “Stack-Based Execution”">​</a></h3><p>The ORGASM VM uses an operand stack:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Before:   stack = [a, b]</span></span>
<span class="line"><span>Instruction: ADD</span></span>
<span class="line"><span>After:    stack = [a + b]</span></span></code></pre></div><h3 id="call-frames" tabindex="-1">Call Frames <a class="header-anchor" href="#call-frames" aria-label="Permalink to “Call Frames”">​</a></h3><p>Each function call creates a frame with:</p><ul><li><strong>Local variables</strong> — slots for function parameters and locals</li><li><strong>Operand stack</strong> — for intermediate values</li><li><strong>Return address</strong> — where to continue after the call</li><li><strong>Lexical scope</strong> — for closure support</li></ul><h3 id="memory-management" tabindex="-1">Memory Management <a class="header-anchor" href="#memory-management" aria-label="Permalink to “Memory Management”">​</a></h3><p>The VM uses <code>StorageCell</code> slots managed with <code>std::shared_ptr</code>. The managed heap:</p><ul><li>Allocates cells for <code>new</code> expressions</li><li>Tracks references through slot references and call-frame roots</li><li>Runs a tracing garbage collector for cyclic garbage</li><li>Supports finalizers (<code>Drop</code> trait) during collection</li></ul><h3 id="garbage-collection" tabindex="-1">Garbage Collection <a class="header-anchor" href="#garbage-collection" aria-label="Permalink to “Garbage Collection”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Node {</span></span>
<span class="line"><span>    next: ref&lt;Node&gt;;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val a = new Node { next: null };</span></span>
<span class="line"><span>val b = new Node { next: a };</span></span>
<span class="line"><span>a.next = b;   // Creates a cycle — GC handles this</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// When a and b go out of scope, the GC collects the cycle</span></span></code></pre></div><h2 id="safety-features" tabindex="-1">Safety Features <a class="header-anchor" href="#safety-features" aria-label="Permalink to “Safety Features”">​</a></h2><p>The VM includes bounds checking and safety guards:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Bounds-checked array access</span></span>
<span class="line"><span>arr[100];   // Runtime error: index out of bounds</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Stack underflow protection (VM internal)</span></span>
<span class="line"><span>// Use-after-move detection</span></span>
<span class="line"><span>val x = move y;</span></span>
<span class="line"><span>print(y);   // Runtime error: use after move</span></span></code></pre></div><h2 id="performance-considerations" tabindex="-1">Performance Considerations <a class="header-anchor" href="#performance-considerations" aria-label="Permalink to “Performance Considerations”">​</a></h2><ul><li>ORGASM bytecode is significantly faster than AST interpretation</li><li>Native function calls have minimal overhead</li><li>The VM uses direct threaded code execution</li><li>Bytecode modules load faster than source compilation</li></ul><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to “What&#39;s Next?”">​</a></h2><p>Continue to <a href="./imgui-integration">ImGui Integration</a> for GUI programming with NG.</p><blockquote><p><strong>Try it:</strong> Run any example with <code>--run-bytecode</code> to see the VM in action <strong>Try it:</strong> The test suite <code>[OrgasmTest]</code> tag covers all VM features</p></blockquote>`,60)])])}const k=a(t,[["render",l]]);export{g as __pageData,k as default};
